syarah:
[
  {
    "name": "Hasyiyah al-Bajuri 'ala Kifayatil 'Awam",
    "author": "Syaikh Ibrahim al-Bajuri",
    "desc": "Hasyiyah mendalam dalam ilmu aqidah yang menjelaskan kitab Kifayatul 'Awam karya Syaikh Muhammad al-Fudali."
  },
  {
    "name": "Tuhfatul Habib 'ala Syarhil Iqna' (Hasyiyah al-Bujairami 'ala al-Iqna')",
    "author": "Syaikh Sulaiman al-Bujairami",
    "desc": "Hasyiyah luas dan terperinci dalam fiqih Syafi'i yang mengomentari kitab al-Iqna' karya al-Khathib al-Syirbini."
  },
  {
    "name": "Hasyiyah al-Attar 'ala Syarh al-Jalal al-Mahalli 'ala Jam'il Jawami'",
    "author": "Syaikh Hasan al-Attar",
    "desc": "Catatan pinggir tingkat tinggi dalam ushul fiqih yang memperjelas Syarah al-Mahalli atas matan Jam'ul Jawami'."
  },
  {
    "name": "Hasyiyah ad-Dusuqi 'ala al-Syarh al-Kabir",
    "author": "Syaikh Muhammad ad-Dusuqi",
    "desc": "Rujukan utama fiqih madzhab Maliki yang mengomentari al-Syarh al-Kabir karya Imam ad-Dardir."
  },
  {
    "name": "Radd al-Muhtar 'ala al-Durr al-Mukhtar (Hasyiyah Ibnu 'Abidin)",
    "author": "Ibnu 'Abidin al-Shami",
    "desc": "Ensiklopedi fiqih terbesar dan menjadi pegangan utama fatwa dalam madzhab Hanafi."
  },
  {
    "name": "Syarah al-Mahalli 'ala Minhaj at-Thalibin",
    "author": "Imam Jalaluddin al-Mahalli",
    "desc": "Syarah klasik dan sangat presisi atas matan Minhaj at-Thalibin karya Imam an-Nawawi dalam fiqih Syafi'i."
  },
  {
    "name": "Syarah Dahlan 'ala Alfiyah Ibnu Malik",
    "author": "Syaikh Ahmad Zaini Dahlan",
    "desc": "Syarah ilmu nahwu yang populer dan sistematis untuk memahami bait-bait Alfiyah Ibnu Malik."
  },
  {
    "name": "Fathul Qarib al-Mujib fi Syarhi Alfazh al-Taqrib",
    "author": "Ibnu Qasim al-Ghazzi",
    "desc": "Kitab syarah dasar hingga menengah fiqih Syafi'i atas Matan Abu Syuja' yang paling masyhur di pesantren."
  },
  {
    "name": "Kifayatul Akhyar fi Hilli Ghayatil Ikhtishar",
    "author": "Imam Taqiyuddin al-Hishni",
    "desc": "Syarah fiqih Syafi'i tingkat menengah yang disertai dalil-dalil Al-Qur'an dan Hadits secara ringkas padat."
  },
  {
    "name": "Faydh al-Qadir Syarah al-Jami' al-Saghir",
    "author": "Imam Abdurra'uf al-Munawi",
    "desc": "Syarah luas atas kitab hadits al-Jami' al-Saghir karya Imam al-Suyuti yang mencakup analisis sanad dan matan."
  },
  {
    "name": "Fathul Mughith Syarah Alfiyah al-Iraqi",
    "author": "Imam al-Sakhawi",
    "desc": "Syarah paling komprehensif dalam musthalah hadits atas Alfiyah al-Iraqi."
  },
  {
    "name": "Syarah al-Taftazani 'ala al-'Aqa'id an-Nasafiyyah",
    "author": "Imam Sa'duddin at-Taftazani",
    "desc": "Kitab syarah aqidah Ahlus Sunnah wal Jama'ah (Maturidiyyah) yang menggunakan pendekatan logika filsafat Islam."
  },
  {
    "name": "Hasyiyah al-Kafrawi 'ala Matn al-Ajurrumiyyah",
    "author": "Syaikh Hasan al-Kafrawi",
    "desc": "Syarah gramatikal bahasa Arab (Nahwu) beserta contoh i'rab lengkap pada tiap kalimat matan Ajurrumiyyah."
  },
  {
    "name": "Syarah Syudzur adz-Dzahab fi Ma'rifati Kalamil 'Arab",
    "author": "Ibnu Hisham al-Anshari",
    "desc": "Penjelasan mendalam mengenai tata bahasa Arab tingkat menengah karya pengarangnya sendiri."
  },
  {
    "name": "Audhah al-Masalik ila Alfiyyah Ibni Malik",
    "author": "Ibnu Hisham al-Anshari",
    "desc": "Syarah tata bahasa Arab yang menguraikan bait Alfiyah dengan susunan bahasa yang lebih mudah dipahami."
  },
  {
    "name": "Hasyiyah al-Birmawi 'ala Syarh Ghayat al-Thaqrib",
    "author": "Syaikh Ibrahim al-Birmawi",
    "desc": "Catatan kritis dan penjelasan tambahan atas Syarah Ibnu Qasim al-Ghazzi dalam fiqih Syafi'i."
  },
  {
    "name": "Hasyiyah as-Sawi 'ala al-Jauharatut Tauhid",
    "author": "Syaikh Ahmad as-Sawi",
    "desc": "Hasyiyah penting yang menguraikan bait-bait ilmu tauhid dalam kitab Jauharatut Tauhid."
  },
  {
    "name": "Syarah Mukhtasar al-Ma'ani",
    "author": "Imam Sa'duddin at-Taftazani",
    "desc": "Syarah dalam ilmu balaghah (sastra Arab) yang menjadi standar kajian pesantren tingkat tinggi."
  },
  {
    "name": "Hasyiyah ad-Dusuqi 'ala Mukhtasar

